int save_xstate(struct xsave_struct *fx, u64 mask) {
    if (!fx) {
        return -1;
    }

    /* Check for xsaves support */
    if (cpu_has_xsaves) {
        asm volatile("xsaves %0\n"
                   : [fx] "=m"(*fx)
                   : "c"(mask));
    } else if (cpu_has_xsaveopt) {
        asm volatile("xsaveopt %0\n"
                   : [fx] "=m"(*fx)
                   : "c"(mask));
    } else {
        asm volatile("xsave %0\n"
                   : [fx] "=m"(*fx)
                   : "c"(mask));
    }

    return 0;
}
